import React, { Component } from "react";
import Layout from "../../components/Layout";
import Tender from "../../ethereum/tender";
import { Card, Grid, Button } from "semantic-ui-react";
import web3 from "../../ethereum/web3";
import { Link } from "../../routes";

const BidDisplay = ({address,bidAmount, bid}) => {
  const bids  = [bid]
  const renderCards = () => {
    const items = [
          {
            header: bidAmount,
            meta: "ID of the Bid",
            description:
              "The unique identification number of the given bid.",
            style: { overflowWrap: "break-word" }
          },
          {
            header: bid,
            meta: "Bid Amount",
            description: "The price of the bid made by the bidder."
          },
    ]
    return <Card.Group items={items} />;
  };
   
  // const renderCards = () => {
  //   const items = [
  //     {
  //       header: index,
  //       meta: "ID of the Bid",
  //       description:
  //         "The unique identification number of the given bid.",
  //       style: { overflowWrap: "break-word" }
  //     },
  //     {
  //       header: bidAmount,
  //       meta: "Bid Amount",
  //       description: "The price of the bid made by the bidder."
  //     },
  //     {
  //       header: description,
  //       meta: "Description",
  //       description:
  //         "Proposal of the bidder."
  //     }
  //   ];
  //   return <Card.Group items={items} />;
  // };


  return (
    <Layout>
      <h3>Bid Show</h3>
      <Grid>
        <Grid.Row>
          <Grid.Column width={10}>{renderCards()}</Grid.Column>
          <Grid.Column width={6}></Grid.Column>
        </Grid.Row>
        <Grid.Row>
          <Grid.Column>
            <Link route={`/tenders/${address}`}>
              <a>
                <Button primary>Details of the tender.</Button>
              </a>
            </Link>
          </Grid.Column>
        </Grid.Row>
      </Grid>
    </Layout>
  );
};

export const getServerSideProps = async (props)  => {
  const tender = Tender(props.query.address);
  const numberOfBids = await tender.methods.numberOfBids.call();
  console.log('EXECUTED');
  const bid0 = await tender.methods.publicBids(0).call();
  
  const bids = [...new Array(numberOfBids)].map(async (num, index) => {
    const bid = await tender.methods.publicBids(index).call();
    console.log('BID')
     return JSON.stringify(bid);
  })
  
  return {
    props: {
      adddress: props.query.address,
      bidAmount: bid0.bidAmount,
      bid: bid0.bid
    }
    // props : {bids}
  };

};

export default BidDisplay;
